/**
 * @method
 * @name readDetailInfo
 * @description read Detail Info 처리
 * @param {*} securitiesType securitiesType
 * @param {String} isuCd isuCd
 * @returns {void}
 * @hidden N
 */
scwin.readDetailInfo = function (securitiesType, isuCd) {
    let title = "";
    let width = "600";
    let height = "400";
    let methodName = "";
    const icuCd = "";
    let url = "";
    const left = '10';
    const top = '10';
    let scrollbars = 'no';
    if (securitiesType === "STK") {
        title = "주권";
        width = "600";
        height = "460";
        scrollbars = "yes";
        methodName = "readStockDetailed";
    } else {
        if (securitiesType === "BND") {
            title = "채권";
            width = "618";
            height = "500";
            scrollbars = "yes";
            methodName = "readBondDetailed";
        } else {
            if (securitiesType === "FUT_OPT") {
                title = "선물옵션";
                width = "600";
                height = "450";
                methodName = "readFutureOptionsDetailed";
            } else {
                if (securitiesType === "BC") {
                    title = "수익증권";
                    width = "600";
                    height = "420";
                    methodName = "readBeneficiaryCertDetailed";
                } else {
                    if (securitiesType === "BW") {
                        title = "신주인수권증권";
                        width = "600";
                        height = "500";
                        methodName = "readDRCodeDetailed";
                    } else {
                        if (securitiesType === "ELW") {
                            title = "주식워런트(ELW)";
                            width = "600";
                            height = "750";
                            methodName = "readRightWarrantCodeDetailed";
                        } else {
                            if (securitiesType === "CD") {
                                title = "CD";
                                width = "600";
                                height = "500";
                                methodName = "readCDCodeDetailed";
                            } else {
                                if (securitiesType === "CP") {
                                    title = "CP";
                                    width = "600";
                                    height = "500";
                                    methodName = "readCPCodeDetailed";
                                } else {
                                    if (securitiesType === "DR") {
                                        title = "유가증권예탁증서(DR)";
                                        width = "600";
                                        height = "500";
                                        methodName = "readDepositReceiptCodeDetailed";
                                    } else {
                                        if (securitiesType === "INDX") {
                                            title = "지표";
                                            width = "600";
                                            height = "500";
                                            methodName = "readIndexCodeDetailed";
                                        } else {
                                            if (securitiesType === "STRIP") {
                                                title = "스트립";
                                                width = "800";
                                                height = "500";
                                                scrollbars = "yes";
                                                methodName = "readStripCodeDetailed";
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    if (url != null && url !== "STRIP") {
        url = (String(((dma_pageContext.get("DST_URL") ?? "")) == null ? '' : ((dma_pageContext.get("DST_URL") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("DST_URL") ?? "")) == null ? '' : ((dma_pageContext.get("DST_URL") ?? "")))) + "/corpgeneral/securities.do?method=" + methodName + "&isuCd=" + isuCd;
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), String('' || '').split(',').reduce(function (o, kv) { const p = kv.split('='); const k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, (typeof title !== 'undefined' ? title : '') ? Object.assign({ scrollbars: false, resizable: false, width: "", height: "", type: "pageFramePopup" }, { id: (typeof title !== 'undefined' ? title : '') }) : { scrollbars: false, resizable: false, width: "", height: "", type: "pageFramePopup" }), {});
    }
};
